SELECT *, AVG(unit_price) OVER w_running AS order_id_avg_unit_price, ROUND(quantity / SUM(quantity) OVER (PARTITION BY product_id), 4) AS quantity_share, ROW_NUMBER() OVER w_grp AS row_seq, SUM(unit_price) OVER (PARTITION BY order_id ORDER BY quantity ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_unit_price, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY quantity ASC, id ASC) AS row_seq_2 FROM order_items WINDOW w_running AS (PARTITION BY order_id), w_grp AS (PARTITION BY order_id ORDER BY unit_price ASC, id ASC);
